package writer

import "github.com/PorticoMediaServer/portico/server/internal/store/stmt"

func mpHLSDomainDefinitions() []stmt.Definition {
	specs := []struct {
		id, sql, types string
		kind           stmt.Kind
	}{
		{"mp.hls.reserve_insert", `INSERT INTO playback_hls_reservations(session_id,bytes) VALUES(?,?) RETURNING 1`, "si", stmt.Write},
		{"mp.hls.reserve_update", `UPDATE playback_hls_reservations SET bytes=? WHERE session_id=? AND bytes=? RETURNING 1`, "isi", stmt.Write},
		{"mp.hls.plan_insert", `INSERT INTO mp_hls_plans(session_id,plan_digest,timeline_kind,timeline_digest,backend,strategy,rendition_count,segment_count,duration_us,source_size,source_modified_ns,staged_count,sealed) VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0) RETURNING 1`, "ssisssiiiii", stmt.Write},
		{"mp.hls.rendition_insert", `INSERT INTO mp_hls_renditions(session_id,rendition_id,ordinal,codec,container,init_name,bitrate,width,height,plan_digest) SELECT ?,?,?,?,?,?,?,?,?,p.plan_digest FROM mp_hls_plans AS p WHERE p.session_id=? AND p.plan_digest=? AND p.sealed=0 AND ?<p.rendition_count RETURNING 1`, "ssisssiiissi", stmt.Write},
		{"mp.hls.plan_stage_advance", `UPDATE mp_hls_plans SET staged_count=(SELECT count(*) FROM mp_hls_renditions AS r WHERE r.session_id=mp_hls_plans.session_id AND r.plan_digest=mp_hls_plans.plan_digest),sealed=CASE WHEN (SELECT count(*) FROM mp_hls_renditions AS r WHERE r.session_id=mp_hls_plans.session_id AND r.plan_digest=mp_hls_plans.plan_digest)=rendition_count THEN 1 ELSE 0 END WHERE session_id=? AND plan_digest=? AND sealed=0 RETURNING 1`, "ss", stmt.Write},
		{"mp.hls.claim_plan", `SELECT p.rendition_count,p.backend FROM mp_hls_plans AS p CROSS JOIN playback_hls_reservations AS r ON r.session_id=p.session_id WHERE p.session_id=? AND p.plan_digest=? AND p.sealed=1 AND p.rendition_count BETWEEN 1 AND 32 AND p.segment_count>? AND r.bytes=?`, "ssii", stmt.Read},
		{"mp.hls.window_insert", `INSERT INTO playback_hls_windows(session_id,start_index,status,highest_produced,started_at_ms,mp_physical_generation,mp_execution_id,mp_source_request_id,mp_execution_generation,mp_revision,mp_end_index,mp_plan_digest,mp_writes_retired,mp_exit_confirmed,mp_cleaned,mp_exit_digest,mp_cleanup_cursor) VALUES(?,?,'running',?,?,?,?,?,1,1,?,?,0,0,0,'',0) RETURNING 1`, "siiiissis", stmt.Write},
		{"mp.hls.window_reclaim", `UPDATE playback_hls_windows SET status='running',highest_produced=start_index-1,started_at_ms=?,mp_execution_id=?,mp_physical_generation=?,mp_end_index=?,mp_plan_digest=?,mp_source_request_id=?,mp_execution_generation=mp_execution_generation+1,mp_revision=mp_revision+1,mp_writes_retired=0,mp_exit_confirmed=0,mp_cleaned=0,mp_exit_digest='',mp_cleanup_cursor=0 WHERE session_id=? AND start_index=? AND mp_revision=? AND mp_execution_generation=? AND mp_execution_id=? AND mp_physical_generation=? AND mp_source_request_id=? AND status IN('failed','complete') AND mp_exit_confirmed=1 AND mp_cleaned=1 AND NOT EXISTS(SELECT 1 FROM mp_hls_window_renditions AS r WHERE r.session_id=playback_hls_windows.session_id AND r.window_start=playback_hls_windows.start_index AND r.window_generation=playback_hls_windows.mp_execution_generation) AND NOT EXISTS(SELECT 1 FROM mp_hls_artifacts AS a WHERE a.session_id=playback_hls_windows.session_id AND a.window_start=playback_hls_windows.start_index AND a.window_generation=playback_hls_windows.mp_execution_generation) RETURNING 1`, "isiisssiiisis", stmt.Write},
		{"mp.hls.window_progress_seed", `INSERT INTO mp_hls_window_renditions(session_id,window_start,window_generation,rendition_id,highest_produced) SELECT ?,?,?,r.rendition_id,? FROM mp_hls_renditions AS r WHERE r.session_id=? AND r.plan_digest=?`, "siiiss", stmt.Write},
		{"mp.hls.window_octets", `SELECT octet_length(mp_execution_id)+octet_length(mp_source_request_id)+octet_length(mp_plan_digest)+octet_length(mp_exit_digest) FROM playback_hls_windows WHERE session_id=? AND start_index=? AND mp_execution_id=? AND mp_execution_generation=? AND mp_revision=? AND mp_physical_generation=? AND mp_source_request_id=?`, "sisiiis", stmt.Read},
		{"mp.hls.window_current", `SELECT c.mp_execution_id,c.mp_execution_generation,c.mp_revision,c.mp_physical_generation,c.mp_end_index,c.mp_plan_digest,c.mp_writes_retired,c.mp_exit_confirmed,c.mp_cleaned,c.mp_exit_digest,c.mp_cleanup_cursor,c.status,c.highest_produced,p.backend,c.mp_source_request_id FROM playback_hls_windows AS c CROSS JOIN mp_hls_plans AS p ON p.session_id=c.session_id AND p.plan_digest=c.mp_plan_digest WHERE c.session_id=? AND c.start_index=?`, "si", stmt.Read},
		{"mp.hls.artifact_insert", `INSERT INTO mp_hls_artifacts(session_id,rendition_id,segment_index,kind,name,digest,size,start_us,end_us,decode_from_us,window_start,window_generation,execution_id,occurrence_generation,plan_digest,status) SELECT ?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'published' FROM mp_hls_renditions AS r CROSS JOIN playback_hls_windows AS c ON c.session_id=r.session_id WHERE r.session_id=? AND r.rendition_id=? AND r.plan_digest=c.mp_plan_digest AND ((?=2 AND r.init_name=?) OR (?=1)) AND c.start_index=? AND c.mp_execution_generation=? AND c.mp_execution_id=? AND c.mp_writes_retired=0 AND c.mp_exit_confirmed=0 AND c.mp_revision=? AND c.mp_source_request_id=? AND c.mp_physical_generation=? RETURNING 1`, "ssiissiiiiiisisssisiiisisi", stmt.Write},
		{"mp.hls.progress_advance", `UPDATE mp_hls_window_renditions SET highest_produced=? WHERE session_id=? AND window_start=? AND window_generation=? AND rendition_id=? AND highest_produced=? RETURNING 1`, "isiisi", stmt.Write},
		{"mp.hls.barrier", `UPDATE playback_hls_windows SET highest_produced=max(highest_produced,(SELECT min(r.highest_produced) FROM mp_hls_window_renditions AS r WHERE r.session_id=? AND r.window_start=? AND r.window_generation=?)),status=CASE WHEN (SELECT min(r.highest_produced) FROM mp_hls_window_renditions AS r WHERE r.session_id=? AND r.window_start=? AND r.window_generation=?) >= mp_end_index AND NOT EXISTS(SELECT 1 FROM mp_hls_renditions AS r WHERE r.session_id=playback_hls_windows.session_id AND r.init_name<>'' AND NOT EXISTS(SELECT 1 FROM mp_hls_artifacts AS a WHERE a.session_id=r.session_id AND a.rendition_id=r.rendition_id AND a.kind=2 AND a.name=r.init_name AND a.plan_digest=r.plan_digest AND a.status='published')) THEN 'complete' ELSE status END WHERE session_id=? AND start_index=? AND (SELECT count(*) FROM mp_hls_window_renditions AS r WHERE r.session_id=? AND r.window_start=? AND r.window_generation=?)=(SELECT p.rendition_count FROM mp_hls_plans AS p WHERE p.session_id=? AND p.plan_digest=? AND p.sealed=1) RETURNING highest_produced,status`, "siisiisisiiss", stmt.Write},
		{"mp.hls.window_publish_revision", `UPDATE playback_hls_windows SET mp_revision=mp_revision+1 WHERE session_id=? AND start_index=? AND mp_revision=? AND mp_execution_generation=? AND mp_execution_id=? AND mp_writes_retired=0 AND mp_exit_confirmed=0 AND mp_source_request_id=? RETURNING 1`, "siiiss", stmt.Write},
		{"mp.hls.delivery_ready", `UPDATE playback_sessions SET mp_delivery_ready=CASE WHEN (SELECT highest_produced FROM playback_hls_windows WHERE session_id=playback_sessions.id AND start_index=?)>=? AND NOT EXISTS(SELECT 1 FROM mp_hls_renditions AS r WHERE r.session_id=playback_sessions.id AND r.init_name<>'' AND NOT EXISTS(SELECT 1 FROM mp_hls_artifacts AS a WHERE a.session_id=r.session_id AND a.rendition_id=r.rendition_id AND a.name=r.init_name AND a.kind=2 AND a.status='published' AND a.plan_digest=r.plan_digest)) THEN 1 ELSE mp_delivery_ready END,mp_revision=mp_revision+1 WHERE id=? AND mp_revision=? AND generation=? AND mp_execution_id=? AND mp_retired_generation<generation AND mp_exited_generation<generation RETURNING mp_delivery_ready`, "iisiis", stmt.Write},
		{"mp.hls.demand", `INSERT INTO playback_hls_demand(session_id,highest_served,throttled) VALUES(?,?,?) ON CONFLICT(session_id) DO UPDATE SET highest_served=max(playback_hls_demand.highest_served,excluded.highest_served),throttled=excluded.throttled RETURNING highest_served,throttled`, "sii", stmt.Write},
		{"mp.hls.throttle", `UPDATE playback_hls_windows SET status=CASE WHEN ?=1 THEN 'throttled' ELSE 'running' END WHERE session_id=? AND start_index=? AND EXISTS(SELECT 1 FROM playback_hls_windows AS c WHERE c.session_id=playback_hls_windows.session_id AND c.start_index=playback_hls_windows.start_index AND c.mp_execution_id=? AND c.mp_execution_generation=? AND c.mp_revision=? AND c.mp_source_request_id=? AND c.mp_writes_retired=0 AND c.mp_exit_confirmed=0) AND status IN('running','throttled') RETURNING 1`, "isisiis", stmt.Write},
		{"mp.hls.window_control_revision", `UPDATE playback_hls_windows SET mp_revision=mp_revision+1 WHERE session_id=? AND start_index=? AND mp_execution_id=? AND mp_execution_generation=? AND mp_revision=? AND mp_source_request_id=? RETURNING 1`, "sisiis", stmt.Write},
		{"mp.hls.window_cancel", `UPDATE playback_hls_windows SET status='failed',mp_writes_retired=?,mp_revision=mp_revision+1 WHERE session_id=? AND start_index=? AND mp_execution_generation=? AND mp_execution_id=? AND mp_revision=? AND mp_writes_retired=0 AND mp_exit_confirmed=0 AND mp_source_request_id=? RETURNING 1`, "isiisis", stmt.Write},
		{"mp.hls.window_exit", `UPDATE playback_hls_windows SET mp_writes_retired=1,mp_exit_confirmed=1,mp_exit_digest=?,mp_cleanup_cursor=?,mp_cleaned=?,mp_revision=mp_revision+1 WHERE session_id=? AND start_index=? AND mp_execution_generation=? AND mp_execution_id=? AND mp_revision=? AND mp_cleanup_cursor=? AND mp_cleaned=0 AND (mp_writes_retired>0 OR status='complete') AND (mp_exit_confirmed=0 OR mp_exit_digest=?) AND mp_source_request_id=? AND mp_physical_generation=? RETURNING 1`, "siisiisiissi", stmt.Write},
		{"mp.hls.prepared_version", `SELECT 1 FROM prepared_media_session_pins AS p CROSS JOIN prepared_media_versions AS v ON v.id=p.version_id WHERE p.session_id=? AND p.version_id=? AND p.digest=? AND p.size=? AND v.digest=p.digest AND v.size=p.size AND v.state='published'`, "sssi", stmt.Read},
		{"mp.hls.remote_version", `SELECT 1 FROM mp_remote_delivery_inputs WHERE media_session_id=? AND origin_version=? AND descriptor_version=? AND size=?`, "sssi", stmt.Read},
		{"mp.hls.direct_insert", `INSERT INTO mp_direct_delivery(session_id,source_version,descriptor_version,backend,size,occurrence_generation,execution_id,prepared_version_id,artifact_digest) VALUES(?,?,?,?,?,?,?,?,?) RETURNING 1`, "ssssiisss", stmt.Write},
		{"mp.hls.direct_delete", `DELETE FROM mp_direct_delivery WHERE session_id=? AND source_version=? AND occurrence_generation=? AND execution_id=? AND NOT EXISTS(SELECT 1 FROM mp_media_read_pins AS r WHERE r.media_session_id=mp_direct_delivery.session_id) RETURNING 1`, "ssis", stmt.Write},
		{"mp.hls.direct_ready", `UPDATE playback_sessions SET mp_delivery_ready=1,state='ready',mp_revision=mp_revision+1 WHERE id=? AND mp_revision=? AND generation=? AND mp_execution_id=? AND mp_retired_generation<generation AND mp_exited_generation<generation RETURNING 1`, "siis", stmt.Write},
		{"mp.hls.read_pin", `INSERT INTO mp_media_read_pins(pin_id,media_session_id,execution_id,occurrence_generation,source_version,artifact_digest,from_byte,size) SELECT ?,?,?,?,?,?,?,? FROM mp_direct_delivery AS d WHERE d.session_id=? AND d.source_version=? AND d.size>=? AND d.occurrence_generation=? AND d.execution_id=? AND d.artifact_digest=? RETURNING 1`, "sssissiissiiss", stmt.Write},
		{"mp.hls.artifact_read_pin", `INSERT INTO mp_media_read_pins(pin_id,media_session_id,execution_id,occurrence_generation,source_version,artifact_digest,from_byte,size) SELECT ?,?,?,?,?,?,?,? FROM mp_hls_artifacts AS a WHERE a.session_id=? AND a.rendition_id=? AND a.segment_index=? AND a.kind=? AND a.digest=? AND a.size>=? AND a.status='published' AND a.occurrence_generation=? RETURNING 1`, "sssissiissiisii", stmt.Write},
		{"mp.hls.read_unpin", `DELETE FROM mp_media_read_pins WHERE pin_id=? AND media_session_id=? AND execution_id=? AND occurrence_generation=? RETURNING 1`, "sssi", stmt.Write},
		{"mp.hls.artifact_retire", `UPDATE mp_hls_artifacts SET status='deleting' WHERE session_id=? AND rendition_id=? AND segment_index=? AND kind=? AND name=? AND digest=? AND size=? AND window_start=? AND window_generation=? AND execution_id=? AND status='published' AND NOT EXISTS(SELECT 1 FROM mp_media_read_pins AS r WHERE r.media_session_id=mp_hls_artifacts.session_id AND r.artifact_digest=mp_hls_artifacts.digest) AND EXISTS(SELECT 1 FROM playback_hls_windows AS c WHERE c.session_id=mp_hls_artifacts.session_id AND c.start_index=mp_hls_artifacts.window_start AND c.mp_execution_generation=mp_hls_artifacts.window_generation AND c.mp_execution_id=mp_hls_artifacts.execution_id AND c.mp_exit_confirmed=1) RETURNING 1`, "ssiissiiis", stmt.Write},
		{"mp.hls.artifact_delete", `DELETE FROM mp_hls_artifacts WHERE session_id=? AND rendition_id=? AND segment_index=? AND kind=? AND digest=? AND size=? AND window_start=? AND window_generation=? AND execution_id=? AND status='deleting' AND NOT EXISTS(SELECT 1 FROM mp_media_read_pins AS r WHERE r.media_session_id=mp_hls_artifacts.session_id AND r.artifact_digest=mp_hls_artifacts.digest) RETURNING 1`, "ssiisiiis", stmt.Write},
		{"mp.hls.reserve_release", `DELETE FROM playback_hls_reservations WHERE session_id=? AND bytes=? AND NOT EXISTS(SELECT 1 FROM mp_hls_artifacts AS a WHERE a.session_id=playback_hls_reservations.session_id) AND NOT EXISTS(SELECT 1 FROM playback_hls_windows AS c WHERE c.session_id=playback_hls_reservations.session_id AND c.mp_cleaned=0) AND NOT EXISTS(SELECT 1 FROM mp_media_read_pins AS r WHERE r.media_session_id=playback_hls_reservations.session_id) RETURNING 1`, "si", stmt.Write},
		{"mp.hls.window_progress_delete", `DELETE FROM mp_hls_window_renditions WHERE session_id=? AND window_start=? AND window_generation=? AND rendition_id=? AND EXISTS(SELECT 1 FROM playback_hls_windows AS c WHERE c.session_id=mp_hls_window_renditions.session_id AND c.start_index=mp_hls_window_renditions.window_start AND c.mp_execution_generation=mp_hls_window_renditions.window_generation AND c.mp_execution_id=? AND c.mp_cleaned=1 AND c.mp_exit_confirmed=1) AND NOT EXISTS(SELECT 1 FROM mp_hls_artifacts AS a WHERE a.session_id=mp_hls_window_renditions.session_id AND a.window_start=mp_hls_window_renditions.window_start AND a.window_generation=mp_hls_window_renditions.window_generation AND a.rendition_id=mp_hls_window_renditions.rendition_id) RETURNING 1`, "siiss", stmt.Write},
	}
	var d []stmt.Definition
	for _, s := range specs {
		v := mpPrepDefinition(s.id, s.sql, s.types, s.kind)
		v.CallSites = []string{"store/writer/mp_hls_domain.go"}
		d = append(d, v)
	}
	return d
}
